function jvw_catalog():array{$raw=is_file(JVW_MASTER)?file_get_contents(JVW_MASTER):false;$m=$raw?json_decode($raw,true):null;if(!is_array($m))throw new RuntimeException('Accounting master unavailable.');$out=[];foreach((array)($m['chart']??[])as$a){if(!is_array($a)||empty($a['code']))continue;$level=(string)($a['level']??'');if($level==='heading'||($level==='control'&&empty($a['subledger'])))continue;$out[(string)$a['code']]=$a;}foreach((array)($m['peopleSubledgers']??[])as$a)if(is_array($a)&&!empty($a['code']))$out[(string)$a['code']]=array_merge(['level'=>'subledger','subledger'=>false],$a);ksort($out);return $out;}
