elseif($action==='approve_jv'){$id=trim((string)($b['id']??''));$r=&$s['jvDrafts'][$id];if(!is_array($r)||($r['entity']??'')!==$e||($r['status']??'')!=='Pending Approval')jvw_out(['ok'=>false,'error'=>'Pending JV was not found.'],404);if(($u['role']??'')!=='Super Admin'&&(int)($r['createdByUserId']??0)===(int)($u['id']??0))jvw_out(['ok'=>false,'error'=>'The preparer cannot approve their own JV.'],403);$jid=jvw_post($s,$r,$u);$result=['jvId'=>$id,'journalId'=>$jid,'status'=>'Posted'];unset($r);}
elseif($action==='reject_jv'){$id=trim((string)($b['id']??''));$reason=jvw_text($b['reason']??'',300,'Rejection reason',true);$r=$s['jvDrafts'][$id]??null;if(!is_array($r)||($r['entity']??'')!==$e||($r['status']??'')!=='Pending Approval')jvw_out(['ok'=>false,'error'=>'Pending JV was not found.'],404);$s['jvDrafts'][$id]['status']='Rejected';$s['jvDrafts'][$id]['rejectionReason']=$reason;$s['jvDrafts'][$id]['rejectedAt']=gmdate('c');$s['jvDrafts'][$id]['rejectedBy']=(string)($u['full_name']??$u['username']??'Approver');$s['jvDrafts'][$id]['updatedAt']=gmdate('c');$result=['jvId'=>$id,'status'=>'Rejected'];}
elseif($action==='cancel_jv'){$id=trim((string)($b['id']??''));$r=$s['jvDrafts'][$id]??null;if(!is_array($r)||($r['entity']??'')!==$e||!in_array(($r['status']??''),['Draft','Rejected'],true))jvw_out(['ok'=>false,'error'=>'Only Draft or Rejected JVs can be cancelled.'],409);$s['jvDrafts'][$id]['status']='Cancelled';$s['jvDrafts'][$id]['cancelledAt']=gmdate('c');$s['jvDrafts'][$id]['cancelledBy']=(string)($u['full_name']??$u['username']??'Accounts');$s['jvDrafts'][$id]['updatedAt']=gmdate('c');$result=['jvId'=>$id,'status'=>'Cancelled'];}
